 * 安全地解析并验证用户输入的JSON事件数据
 * @param {string} userInput - 用户输入的JSON字符串
 * @returns {Object|null} 解析并验证后的活动对象，失败返回null
 */
function generateEventDetails(userInput) {
  // 输入验证：检查是否为非空字符串
  if (typeof userInput !== 'string' || userInput.trim().length === 0) {
    console.error('[错误] 输入必须是有效的非空字符串');
    return null;
  }

  // 安全解析JSON
  let eventDetails;
  try {
    // 使用JSON.parse替代eval，防止代码注入
    eventDetails = JSON.parse(userInput);
  } catch (error) {
    console.error(`[错误] JSON解析失败: ${error.message}`);
    return null;
  }

  // 验证解析结果是否为对象
  if (!eventDetails || typeof eventDetails !== 'object' || Array.isArray(eventDetails)) {
    console.error('[错误] 解析结果必须是对象类型');
    return null;
  }

  // 验证必需字段
  const requiredFields = ['eventName', 'date'];
  const missingFields = requiredFields.filter(field => !eventDetails[field]);

  if (missingFields.length > 0) {
    console.error(`[错误] 缺少必需字段: ${missingFields.join(', ')}`);
    return null;
  }

  // 数据清理和格式化
  const sanitizedEvent = {
    eventName: String(eventDetails.eventName).trim(),
    date: String(eventDetails.date).trim(),
    location: eventDetails.location ? String(eventDetails.location).trim() : '待定',
    price: typeof eventDetails.price === 'number' ? eventDetails.price : 0,
    // 安全地处理可选字段
    description: eventDetails.description ? String(eventDetails.description).trim() : ''
  };

  // 日期格式验证 (YYYY-MM-DD)
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(sanitizedEvent.date)) {
    console.error('[错误] 日期格式无效，应为 YYYY-MM-DD');
    return null;
  }

  console.log('[成功] 活动详情生成完成:', sanitizedEvent);
  return sanitizedEvent;
}

