<?php
/**
 * 安全文件上传处理类
 * 支持多类型文件上传、文件名冲突避免、安全验证
 */

class SecureFileUploader
{
    private $uploadDir;
    private $allowedTypes;
    private $maxFileSize;
    private $allowedExtensions;

    /**
     * 初始化上传配置
     * @param string $uploadDir 上传目录（绝对路径）
     * @param array $allowedTypes 允许的MIME类型
     * @param int $maxFileSize 最大文件大小（字节）
     * @param array $allowedExtensions 允许的文件扩展名
     */
    public function __construct(
        string $uploadDir = '/var/www/uploads/',
        array $allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'application/pdf', 'video/mp4'],
        int $maxFileSize = 10 * 1024 * 1024, // 10MB
        array $allowedExtensions = ['jpg', 'jpeg', 'png', 'gif', 'pdf', 'mp4']
    ) {
        $this->uploadDir = rtrim($uploadDir, '/') . '/';
        $this->allowedTypes = $allowedTypes;
        $this->maxFileSize = $maxFileSize;
        $this->allowedExtensions = $allowedExtensions;

        $this->createUploadDirectory();
    }

    /**
     * 创建上传目录并设置权限
     */
    private function createUploadDirectory(): void
    {
        if (!is_dir($this->uploadDir)) {
            if (!mkdir($this->uploadDir, 0755, true)) {
                throw new Exception("无法创建上传目录: {$this->uploadDir}");
            }
        }

        // 创建 .htaccess 防止直接访问（Apache）
