     * @param string $password 用户输入的明文密码
     * @return string|false 返回哈希后的密码或false
     */
    public static function hashPassword($password)
    {
        // 验证密码长度
        if (strlen($password) < 8) {
            error_log("密码长度不足8位");
            return false;
        }

        // 优先使用 Argon2id（PHP 7.3+），否则使用 Bcrypt
        $options = [];
        if (defined('PASSWORD_ARGON2ID')) {
            $algorithm = PASSWORD_ARGON2ID;
            $options = [
                'memory_cost' => 65536,  // 64MB
                'time_cost' => 4,
                'threads' => 3
            ];
        } else {
            $algorithm = PASSWORD_BCRYPT;
            $options = [
                'cost' => 12  // 成本因子（4-31，值越高越安全但越慢）
            ];
        }

        $hashedPassword = password_hash($password, $algorithm, $options);

        if ($hashedPassword === false) {
            error_log("密码哈希失败");
        }

        return $hashedPassword;
    }

    /**
     * 验证密码（用于登录）
     * @param string $password 用户输入的明文密码
     * @param string $hash 数据库中存储的哈希密码
     * @return bool 验证成功返回true，失败返回false
     */
    public static function verifyPassword($password, $hash)
    {
        if (empty($hash) || strlen($hash) < 60) {
            return false;
        }

        return password_verify($password, $hash);
    }

    /**
     * 检查密码是否需要重新哈希（用于算法升级）
