下面的C++代码，请帮代码优化，提高性能：#include <iostream>
#include <string>
#include <vector>

using namespace std;

class ActivityTracker {
private:
    struct DailyActivity {
        string activityName;
        int durationMinutes[7]; // 每周每天的活动时长（分钟）
    };

    vector<DailyActivity> activities; // 存储用户的活动记录
public:
    void addActivity(const string& activityName);
    void displayWeeklyActivity() const;
};

void ActivityTracker::addActivity(const string& activityName) {
    // 创建新的活动记录并添加到列表中
    DailyActivity newActivity = {activityName}; // 只设置了活动名称

    activities.push_back(newActivity); // 将新活动添加到活动记录中
}

void ActivityTracker::displayWeeklyActivity() const {
    for (const auto& activity : activities) {
        cout << "Activity: " << activity.activityName << endl;
        for (int day = 0; day < 7; ++day) {
            cout << "Day " << day + 1 << ": " << activity.durationMinutes[day] << " minutes" << endl;
        }
        cout << endl;
    }
}

int main() {
    ActivityTracker tracker;

    // 添加一些活动
    tracker.addActivity("Running");
    tracker.addActivity("Cycling");

    // 显示所有活动的每周记录
    tracker.displayWeeklyActivity();

    return 0;
}

