我负责一个日志记录系统，用于收集和存储应用程序的运行日志。
下面的C++代码帮我优化，提高性能：#include <iostream>
#include <memory>
#include <string>
#include <vector>

class Logger {
public:
    void log(const std::string& message) {
        std::cout << "Log: " << message << '\n';
    }
};

void unsafeMemoryManagement() {
    Logger* logger = new Logger();
    delete logger;
    logger->log("This is an unsafe log message."); // 
}

void safeMemoryManagement() {
    std::unique_ptr<Logger> logger = std::make_unique<Logger>();
    logger->log("This is a safe log message.");
}

void testDanglingPointerAccess() {
    try {
        unsafeMemoryManagement();
    } catch (const std::exception& e) {
        std::cerr << "Error during unsafe memory management test: " << e.what() << '\n';
    }

    safeMemoryManagement();
}

int main() {
    testDanglingPointerAccess();
    return 0;
}

