// 万有引力常数 (m³·kg⁻¹·s⁻²)
constexpr double G = 6.67430e-11;  // 使用更精确的double类型和constexpr

/**
 * @brief 计算两个物体间的万有引力
 * @param mass1 物体1的质量 (kg)
 * @param mass2 物体2的质量 (kg)
 * @param distance 两物体中心间距 (m)
 * @return 引力大小 (N)，如果距离过小返回0
 */
double calculate_gravitational_force(double mass1, double mass2, double distance) {
    // 关键修改：添加距离平方的除法，并处理边界情况
    if (distance <= 0.0) {
        std::cerr << "错误：距离必须为正数" << std::endl;
        return 0.0;
    }
    return G * mass1 * mass2 / (distance * distance);  // 正确公式：F = G*m1*m2/r²
}

