				lastErr = fmt.Errorf("请求超时 (超时时间: %v): %w", c.timeout, err)
			} else {
				lastErr = fmt.Errorf("请求失败: %w", err)
			}
			continue
		}

		// 检查HTTP状态码
		if resp.StatusCode != http.StatusOK {
			resp.Body.Close()
			lastErr = fmt.Errorf("HTTP状态码错误: %d %s", resp.StatusCode, resp.Status)
			if resp.StatusCode >= 500 {
				// 服务器错误，继续重试
				continue
			}
			// 客户端错误，不重试
			return nil, lastErr
		}

		// 读取响应体
		body, err := io.ReadAll(resp.Body)
		resp.Body.Close()
		if err != nil {
			lastErr = fmt.Errorf("读取响应失败: %w", err)
			continue
		}

		// 成功获取数据
		return body, nil
	}

	return nil, fmt.Errorf("经过%d次重试后仍然失败: %w", c.retryCount, lastErr)
