package main

import (
	"fmt"
	"io"
	"os"
)

// readFile 读取文件内容并返回字符串和错误
func readFile(filePath string) (string, error) {
	// 打开文件
	file, err := os.Open(filePath)
	if err != nil {
		return "", fmt.Errorf("无法打开文件: %w", err)
	}
	// 确保函数返回时关闭文件（对应Python的with语句）
	defer file.Close()

	// 读取全部内容
	content, err := io.ReadAll(file)
	if err != nil {
		return "", fmt.Errorf("无法读取文件: %w", err)
	}

	// 将字节切片转换为字符串
	return string(content), nil
}

func main() {
	// 示例：读取当前目录下的test.txt文件
	filePath := "test.txt"

	content, err := readFile(filePath)
	if err != nil {
		fmt.Printf("错误: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("文件内容:\n%s\n", content)
}
```

**关键修改点说明：**

1. **错误处理机制**：Go使用显式的多返回值错误处理（`string, error`）而非Python的异常机制，调用者必须检查`err`是否为`nil`

2. **资源管理**：使用`defer file.Close()`确保文件在函数退出时关闭，对应Python的`with`语句自动关闭功能

3. **类型转换**：Go的`io.ReadAll()`返回`[]byte`类型，需要显式转换为`string`，而Python自动处理字符串类型

4. **错误包装**：使用`fmt.Errorf("...%w", err)`包装原始错误

