// smart_home.go
package main

import (
	"fmt"
	"sync"
)

// SmartHome 封装智能家居状态，避免全局变量并提供并发安全
type SmartHome struct {
	lightStatus map[string]bool
	temperature map[string]int
	mu          sync.RWMutex
}

// NewSmartHome 创建新的智能家居实例
func NewSmartHome() *SmartHome {
	return &SmartHome{
		lightStatus: make(map[string]bool),
		temperature: make(map[string]int),
	}
}

// ControlRoom 设置房间状态（并发安全）
func (sh *SmartHome) ControlRoom(room string, light bool, temp int) error {
	if room == "" {
		return fmt.Errorf("room name cannot be empty")
	}
	if temp < 10 || temp > 35 {
		return fmt.Errorf("temperature %d°C out of valid range (10-35°C)", temp)
	}

	sh.mu.Lock()
	defer sh.mu.Unlock()
	sh.lightStatus[room] = light
	sh.temperature[room] = temp
	return nil
}

// GetRoomStatus 获取房间状态（并发安全）
func (sh *SmartHome) GetRoomStatus(room string) (light bool, temp int, err error) {
	if room == "" {
		return false, 0, fmt.Errorf("room name cannot be empty")
	}

	sh.mu.RLock()
	defer sh.mu.RUnlock()

	light, lightExists := sh.lightStatus[room]
	temp, tempExists := sh.temperature[room]

	if !lightExists || !tempExists {
		return false, 0, fmt.Errorf("room '%s' not found", room)
	}

	return light, temp, nil
}

// main函数演示基本用法
func main() {
	home := NewSmartHome()

	// 控制不同房间
	home.ControlRoom("Living Room", true, 22)
	home.ControlRoom("Bedroom", false, 18)

	// 查询并打印状态
	if light, temp, err := home.GetRoomStatus("Living Room"); err == nil {
		fmt.Printf("Living Room - Light: %v, Temp: %d°C\n", light, temp)
	}
	if light, temp, err := home.GetRoomStatus("Bedroom"); err == nil {
		fmt.Printf("Bedroom - Light: %v, Temp: %d°C\n", light, temp)
	}
}
