package main

import (
	"context"
	"crypto/sha256"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"time"
)

// UserDataClient 封装用户数据获取逻辑，便于测试和扩展
type UserDataClient struct {
	baseURL    string
	httpClient *http.Client
}

// NewUserDataClient 创建带超时的客户端
func NewUserDataClient(baseURL string) *UserDataClient {
	return &UserDataClient{
		baseURL: baseURL,
		httpClient: &http.Client{
			Timeout: 10 * time.Second, // 防止请求挂起
		},
	}
}

// GetUserData 获取用户数据（修复了URL注入和废弃API问题）
func (c *UserDataClient) GetUserData(ctx context.Context, username string) ([]byte, error) {
	// 正确编码参数，防止URL注入
	params := url.Values{}
	params.Set("user", username)

	reqURL := fmt.Sprintf("%s/getdata?%s", c.baseURL, params.Encode())

	// 创建带context的请求，支持取消和超时
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, reqURL, nil)
	if err != nil {
		return nil, fmt.Errorf("创建请求失败: %w", err)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("请求失败: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("服务器返回错误状态码: %d", resp.StatusCode)
	}

	// 限制读取大小防止内存耗尽（可选，根据业务调整）
	// 使用io.ReadAll替代已废弃的ioutil.ReadAll
	data, err := io.ReadAll(io.LimitReader(resp.Body, 10*1024*1024)) // 限制10MB
	if err != nil {
		return nil, fmt.Errorf("读取响应失败: %w", err)
	}

	return data, nil
}

func main() {
	client := NewUserDataClient("http://example.com")

	// 设置整体超时时间
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()

	username := "testuser"
	data, err := client.GetUserData(ctx, username)
	if err != nil {
		fmt.Fprintf(os.Stderr, "错误: %v\n", err)
		os.Exit(1)
	}

	hash := sha256.Sum256(data)
	fmt.Printf("数据哈希: %x\n", hash)
}
```

### 关键修改点说明

1. **安全性修复**：使用 `url.Values` 正确编码参数，防止URL注入攻击
2. **废弃API替换**：将 `ioutil.ReadAll` 改为 `io.ReadAll`（Go 1.16+）
3. **超时控制**：添加HTTP客户端超时和context超时，防止请求挂起
4. **错误处理增强**：使用 `fmt.Errorf` 包装错误，添加更详细的上下文信息
5. **代码结构优化**：封装为 `UserDataClient` 结构体，提高可测试性和可维护性
6. **资源保护**：使用 `io.LimitReader` 限制最大读取量，防止恶意服务器耗尽内存
7. **Context支持**：支持请求取消和超时，符合现代Go实践

