import java.util.concurrent.ThreadLocalRandom;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.fasterxml.jackson.databind.ObjectMapper;

@WebServlet("/fake_news_generator")
public class FakeNewsGenerator extends HttpServlet {
    private static final Logger logger = LoggerFactory.getLogger(FakeNewsGenerator.class);
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final List<String> FAKE_NEWS_TEMPLATES = List.of(
        "震惊！%s竟藏着这样的惊天秘密！",
        "突发！%s背后的黑幕即将被揭开！",
        "可怕！%s可能会给大家带来灭顶之灾！"
    );
    private static final int MAX_TOPIC_LENGTH = 50;

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        response.setContentType("application/json; charset=UTF-8");
        response.setCharacterEncoding("UTF-8");

        try {
            String topic = request.getParameter("topic");

            // 输入验证
            if (topic == null || topic.trim().isEmpty()) {
                response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
                response.getWriter().write("{\"error\":\"topic参数不能为空\"}");
                return;
            }

            topic = topic.trim();
            if (topic.length() > MAX_TOPIC_LENGTH) {
                response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
                response.getWriter().write("{\"error\":\"topic参数长度不能超过50个字符\"}");
                return;
            }

            // 生成内容
            String generatedFakeNews = generateFakeNews(topic);

            // 构建响应
            NewsResponse newsResponse = new NewsResponse(generatedFakeNews, System.currentTimeMillis());
            String jsonResponse = objectMapper.writeValueAsString(newsResponse);

            response.setStatus(HttpServletResponse.SC_OK);
            response.getWriter().write(jsonResponse);

        } catch (Exception e) {
            logger.error("生成假新闻时发生错误", e);
            response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            response.getWriter().write("{\"error\":\"服务器内部错误\"}");
        }
    }

    private String generateFakeNews(String topic) {
        int index = ThreadLocalRandom.current().nextInt(FAKE_NEWS_TEMPLATES.size());
        String template = FAKE_NEWS_TEMPLATES.get(index);
        return String.format(template, topic);
    }

    // 响应DTO
    private static class NewsResponse {
        public final String content;
        public final long timestamp;

        public NewsResponse(String content, long timestamp) {
            this.content = content;
            this.timestamp = timestamp;
        }
    }
}
