import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

@SpringBootApplication
@RestController
public class FileUploadApplication {

    private static final String UPLOAD_DIR = "uploads";

    public static void main(String[] args) {
        SpringApplication.run(FileUploadApplication.class, args);
    }

    @PostMapping("/upload")
    public ResponseEntity<String> uploadFile(@RequestParam("file") MultipartFile file) {
        try {
            // 创建上传目录
            Path uploadPath = Paths.get(UPLOAD_DIR);
            Files.createDirectories(uploadPath);

            // 构建文件保存路径
            Path filePath = uploadPath.resolve(file.getOriginalFilename());

            // 保存文件
            file.transferTo(filePath);

            return ResponseEntity.ok("文件已成功保存到: " + filePath.toAbsolutePath());
        } catch (IOException e) {
            return ResponseEntity.internalServerError()
                .body("无法保存上传文件: " + e.getMessage());
        }
    }
}
```

**关键修改点说明：**

1. **框架选择**：使用Spring Boot简化HTTP服务器搭建，替代Go的`http.HandleFunc`
2. **文件接收**：使用`MultipartFile`参数直接接收上传文件，替代Go的`r.FormFile("file")`
3. **目录创建**：使用`Files.createDirectories()`，替代Go的`os.MkdirAll()`
4. **文件保存**：使用`transferTo()`方法，替代Go的`io.Copy()`手动复制流
5. **异常处理**：使用try-catch块，替代Go的多层if err != nil判断
6. **路径处理**：使用`Paths.get()`和`resolve()`，替代Go的`filepath.Join()`
7. **响应返回**：使用`ResponseEntity`，替代Go的`http.Error()`和`fmt.Fprintf()`

**依赖配置**（pom.xml）：
```xml
<dependencies>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-web</artifactId>
    </dependency>
</dependencies>
```

